WITH kept_keys AS (SELECT store_id, id FROM inventory EXCEPT ALL SELECT store_id, id FROM inventory WHERE quantity BETWEEN 102 AND 238), verified AS (SELECT s.* FROM inventory s INNER JOIN kept_keys k ON s.store_id = k.store_id AND s.id = k.id) SELECT product_id, CASE WHEN quantity >= 242 THEN 'PREMIUM' ELSE 'STANDARD' END AS quantity_tier, MAX(quantity) AS max_quantity, COUNT(*) AS row_count, ROUND(AVG(quantity), 2) AS avg_quantity, STDDEV_SAMP(quantity) AS quantity_stddev, MIN(quantity) AS min_quantity FROM verified GROUP BY product_id, CASE WHEN quantity >= 242 THEN 'PREMIUM' ELSE 'STANDARD' END ORDER BY row_count DESC NULLS LAST;
